<script>
const slides=[...document.querySelectorAll('.slide')];
const dots=[...document.querySelectorAll('.dot')];
const prev=document.getElementById('prev');
const next=document.getElementById('next');
const stage=document.getElementById('stage');
let current=0;
function render(){
  slides.forEach((s,i)=>{
    s.classList.toggle('active',i===current);
    s.classList.toggle('before',i<current);
  });
  dots.forEach((d,i)=>d.classList.toggle('on',i===current));
  prev.disabled=current===0;
  next.disabled=current===slides.length-1;
}
function goTo(i){ if(i<0||i>=slides.length||i===current) return; current=i; render(); }
prev.onclick=()=>goTo(current-1);
next.onclick=()=>goTo(current+1);
dots.forEach((d,i)=>d.onclick=()=>goTo(i));
document.addEventListener('keydown',e=>{
  const rtl=document.documentElement.dir==='rtl';
  const fwd=rtl?'ArrowLeft':'ArrowRight';
  const back=rtl?'ArrowRight':'ArrowLeft';
  if(e.key===fwd) goTo(current+1);
  if(e.key===back) goTo(current-1);
});
let touchX=null,touchY=null;
stage.addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;touchY=e.touches[0].clientY},{passive:true});
stage.addEventListener('touchend',e=>{
  if(touchX===null) return;
  const dx=e.changedTouches[0].clientX-touchX;
  const dy=e.changedTouches[0].clientY-touchY;
  if(Math.abs(dx)>48 && Math.abs(dx)>Math.abs(dy)*1.25){ if(dx<0) goTo(current+1); else goTo(current-1); }
  touchX=null;touchY=null;
},{passive:true});
render();
</script>
</body>
</html>
