  nav.toc .wrap{padding:0 8px;position:relative;display:flex}
  .navtoggle{display:flex;align-items:center;justify-content:space-between;
    width:100%;max-width:360px;
    background:var(--panel);border:1px solid var(--line);border-radius:12px;
    padding:11px 16px;color:var(--ink);font-family:'Heebo',sans-serif;font-weight:700;cursor:pointer;transition:.18s}
  .navtoggle:hover{border-color:var(--accent)}
  .navtoggle .lbl{display:flex;align-items:center;gap:11px;min-width:0}
  .navtoggle .curdot{flex:0 0 auto;width:26px;height:26px;border-radius:50%;background:var(--accent);
    color:#0b0f17;display:grid;place-items:center;font-family:'Sora',sans-serif;font-weight:700;font-size:12px}
  .navtoggle .curname{font-family:'Heebo',sans-serif;font-weight:700;font-size:15px;color:var(--ink);
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .navtoggle .chev{flex:0 0 auto;color:var(--accent);font-size:13px;transition:.2s;margin-inline-start:10px}
  nav.toc.open .navtoggle .chev{transform:rotate(180deg)}

  .tl{position:absolute;top:calc(100% + 8px);right:8px;width:100%;max-width:360px;z-index:6;
    display:none;flex-direction:column;
    background:var(--panel2);border:1px solid var(--line);border-radius:14px;
    box-shadow:0 18px 50px rgba(0,0,0,.5);padding:6px;max-height:72vh;overflow-y:auto;scrollbar-width:thin}
  nav.toc.open .tl{display:flex}
  .tl a{display:flex;flex-direction:row;align-items:center;gap:12px;
    width:100%;padding:11px 12px;border-radius:9px;text-decoration:none;color:var(--muted);
    font-family:'Heebo',sans-serif;font-size:15px;font-weight:600;text-align:right;transition:.14s}
  .tl a .dot{flex:0 0 auto;width:26px;height:26px;border-radius:50%;
    background:var(--panel);border:1.5px solid var(--line);display:grid;place-items:center;
    font-family:'Sora',sans-serif;font-size:12px;font-weight:700;color:var(--muted);transition:.14s}
  .tl a:hover{background:var(--panel);color:var(--ink)}
  .tl a:hover .dot{border-color:var(--accent);color:var(--ink)}
  .tl a.active{background:var(--panel);color:var(--ink)}
  .tl a.active .dot{border-color:var(--accent);background:var(--accent);color:#0b0f17}

  .progress{display:none}

  @media(min-width:601px){
    nav.toc{padding:14px 0}
    .navtoggle{display:none}
    .tl{display:none !important}
    .progress{display:flex;align-items:center;gap:18px;width:100%}
    .progress .plabel{flex:0 0 auto;display:flex;align-items:center;gap:9px;min-width:148px}
    .progress .plabel .pnum{flex:0 0 auto;width:26px;height:26px;border-radius:50%;background:var(--accent);
      color:#0b0f17;display:grid;place-items:center;font-family:'Sora',sans-serif;font-weight:700;font-size:12px}
    .progress .plabel .pname{font-family:'Heebo',sans-serif;font-weight:700;font-size:15px;color:var(--ink);white-space:nowrap}
    .progress .plabel .pstep{font-family:'Sora',sans-serif;font-size:11px;color:var(--muted);margin-inline-start:2px}
    .ptrack{position:relative;flex:1;height:26px;display:flex;align-items:center;justify-content:space-between}
    .ptrack .pline{position:absolute;right:6px;left:6px;top:50%;height:2px;transform:translateY(-50%);background:var(--line);border-radius:2px}
    .ptrack .pfill{position:absolute;right:6px;top:50%;height:2px;transform:translateY(-50%);background:var(--accent);border-radius:2px;width:0;transition:width .15s ease-out}
    .ptrack a.tick{position:relative;z-index:1;width:13px;height:13px;border-radius:50%;
      background:var(--panel2);border:2px solid var(--line);transition:.16s;cursor:pointer}
    .ptrack a.tick:hover{border-color:var(--accent);transform:scale(1.25)}
    .ptrack a.tick.done{border-color:var(--accent);background:var(--accent)}
    .ptrack a.tick.active{border-color:var(--accent);background:var(--accent);box-shadow:0 0 0 4px rgba(232,178,58,.22);transform:scale(1.25)}
    .ptrack a.tick::after{content:attr(data-name);position:absolute;top:calc(100% + 9px);left:50%;transform:translateX(-50%);
      white-space:nowrap;font-family:'Heebo',sans-serif;font-size:11.5px;font-weight:600;color:var(--muted);
      opacity:0;pointer-events:none;transition:.16s;background:var(--panel2);border:1px solid var(--line);
      border-radius:7px;padding:4px 9px;box-shadow:0 8px 22px rgba(0,0,0,.4);z-index:7}
    .ptrack a.tick:hover::after{opacity:1}
  }
